import messages

def test_removed_fields():
    msgs = [
        {'id':1, 'output':'a', 'model':'x', 'meta':{'a':2}, 'other':'b'},
        {'id':2, 'other':'c'}
    ]
    result = messages.sanitize(msgs)
    for orig, clean in zip(msgs, result):
        for rm in ('id','output','model','meta'):
            assert rm not in clean, f"removed field {rm} still in clean: {clean}"
        # compare with expected excluding removed keys
        expected = {k:v for k,v in orig.items() if k not in ('id','output','model','meta')}
        assert clean == expected, f"clean != expected: {clean} vs {expected}"

def test_preserves_original():
    # original dicts should not be mutated
    msgs = [{'id':1, 'other':'b'}]
    # modify original after sanitization to check no mutation
    msgs[0]['new'] = 'new'
    result = messages.sanitize(msgs)
    # original msgs[0] still has 'new'
    assert 'new' in msgs[0], "original dict was mutated"

def test_preserves_content():
    msgs = [{'id':1, 'output':'a', 'model':'x', 'meta':{'a':2}, 'other':'b'}]
    result = messages.sanitize(msgs)
    orig = msgs[0]
    expected = {k:v for k,v in orig.items() if k not in ('id','output','model','meta')}
    assert result[0] == expected, f"content mismatch: {result[0]} vs {expected}"

if __name__ == '__main__':
    test_removed_fields()
    test_preserves_original()
    test_preserves_content()
    print('All tests passed')
